/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// The infinitive.
    Infinitive,
    /// The non-past: present tense for imperfective verbs, future for perfective ones. (The imperfective future is `буду` + infinitive and is not a form of the verb.)
    NonPast(crate::Person, crate::Number),
    /// The past tense.
    Past(crate::Agreement),
    /// The imperative.
    Imperative(crate::Number),
    /// A participle's citation form (masculine nominative singular); decline it with `adjective`.
    Participle(crate::Participle),
    /// A gerund (adverbial participle).
    Gerund(crate::Tense),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        let cell = match self {
            Cell::Infinitive => cell::INFINITIVE,
            Cell::NonPast(crate::Person::First, crate::Number::Singular) => cell::NON_PAST_1_SG,
            Cell::NonPast(crate::Person::First, crate::Number::Plural) => cell::NON_PAST_1_PL,
            Cell::NonPast(crate::Person::Second, crate::Number::Singular) => cell::NON_PAST_2_SG,
            Cell::NonPast(crate::Person::Second, crate::Number::Plural) => cell::NON_PAST_2_PL,
            Cell::NonPast(crate::Person::Third, crate::Number::Singular) => cell::NON_PAST_3_SG,
            Cell::NonPast(crate::Person::Third, crate::Number::Plural) => cell::NON_PAST_3_PL,
            Cell::Past(crate::Agreement::Masculine) => cell::PAST_M,
            Cell::Past(crate::Agreement::Feminine) => cell::PAST_F,
            Cell::Past(crate::Agreement::Neuter) => cell::PAST_N,
            Cell::Past(crate::Agreement::Plural) => cell::PAST_PL,
            Cell::Imperative(crate::Number::Singular) => cell::IMPERATIVE_SG,
            Cell::Imperative(crate::Number::Plural) => cell::IMPERATIVE_PL,
            Cell::Participle(crate::Participle::PresentActive) => cell::PARTICIPLE_PRES_ACT,
            Cell::Participle(crate::Participle::PastActive) => cell::PARTICIPLE_PAST_ACT,
            Cell::Participle(crate::Participle::PresentPassive) => cell::PARTICIPLE_PRES_PASS,
            Cell::Participle(crate::Participle::PastPassive) => cell::PARTICIPLE_PAST_PASS,
            Cell::Gerund(crate::Tense::Present) => cell::GERUND_PRES,
            Cell::Gerund(crate::Tense::Past) => cell::GERUND_PAST,
        };
        cell as usize
    }
}

impl From<(crate::Person, crate::Number)> for Cell {
    fn from((person, number): (crate::Person, crate::Number)) -> Self {
        Cell::NonPast(person, number)
    }
}

impl From<crate::Agreement> for Cell {
    fn from(agreement: crate::Agreement) -> Self {
        Cell::Past(agreement)
    }
}

impl From<crate::Number> for Cell {
    fn from(number: crate::Number) -> Self {
        Cell::Imperative(number)
    }
}

impl From<crate::Participle> for Cell {
    fn from(participle: crate::Participle) -> Self {
        Cell::Participle(participle)
    }
}

impl From<crate::Tense> for Cell {
    fn from(tense: crate::Tense) -> Self {
        Cell::Gerund(tense)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    full: bool,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            full: false,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its lemma is spelled with every mark the dictionary writes, so
    /// none is hidden (without this, a lemma typed without marks may be
    /// missing some, and its forms are less sure).
    #[must_use]
    pub fn spelled_in_full(mut self) -> Self {
        self.full = true;
        self
    }

    fn known(&self) -> Known<'_, u8> {
        Known {
            forms: &self.given,
            feature: None,
            full: self.full,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, infinitive::Conjugation>> {
        infinitive::GRAMMAR.readings(self.lemma, &self.known())
    }
}
